/* Fade and rise over the first 300px of scroll after the element's top enters the window (a
   fixed distance, so anything in the first screen is already in place at load). Each step
   shifts the range 40px later. Only where view timelines exist and motion is allowed. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .prenuvo-reveal {
      animation: prenuvo-reveal-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--prenuvo-reveal-step, 0) * 40px) entry calc(300px + var(--prenuvo-reveal-step, 0) * 40px);
    }
  }
}

@keyframes prenuvo-reveal-in {
  from {
    opacity: 0;
    transform: translateY(var(--prenuvo-reveal-rise, 80px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./prenuvo-reveal.css";

export interface PrenuvoRevealProps {
  children?: ReactNode;
  /** the element to render (div by default; li inside lists) */
  as?: ElementType;
  /** how far it rises into place, in px (the original uses 64, 80 and 96) */
  rise?: number;
  /** position in a staggered row: 0, 1, 2… each arrives a little later */
  step?: number;
  className?: string;
}

export function PrenuvoReveal({ children, as: Tag = "div", rise = 80, step = 0, className }: PrenuvoRevealProps) {
  return (
    <Tag
      className={cn("prenuvo-reveal", className)}
      style={{ "--prenuvo-reveal-step": step, "--prenuvo-reveal-rise": `${rise}px` } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
